import{Z as t,e as i,f as n,a0 as o}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"LiveChat","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/help-desk/livechat.md","filePath":"integrations/help-desk/livechat.md","lastUpdated":1780377007000}'),a={name:"integrations/help-desk/livechat.md"};function r(s,e,l,h,c,d){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="livechat" tabindex="-1">LiveChat <a class="header-anchor" href="#livechat" aria-label="Permalink to &quot;LiveChat&quot;">​</a></h1><p>Connect LiveChat to send support enquiries to your help-desk account. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Help Desk</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>LiveChat</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-livechat-api" tabindex="-1">Step 2. Connect to the LiveChat API <a class="header-anchor" href="#step-2-connect-to-the-livechat-api" aria-label="Permalink to &quot;Step 2. Connect to the LiveChat API&quot;">​</a></h3><ol><li>Go to <a href="https://developers.livechat.com/console/" target="_blank">LiveChat Developer Console</a> and log in.</li><li>Navigate to <strong>Apps</strong>.</li><li>Click the <strong>Build App</strong> button, and fill out the app name and description.</li><li>Proceed to <strong>Configure a widget</strong> using the default settings.</li><li>Proceed to <strong>Configure Authorization</strong>.</li><li>In the <strong>Redirect URI whitelist</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Copy the <strong>Client ID</strong> from LiveChat and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Client Secret</strong> from LiveChat and paste in the <strong>Client Secret</strong> field in Formie.</li><li>Set the required scopes (such as <code>tickets.write</code> and <code>tickets.read</code>).</li><li>Go to <a href="https://my.livechatinc.com" target="_blank">LiveChat</a>.</li><li>Navigate to <strong>Settings</strong> → <strong>Chat Page</strong>.</li><li>Copy <em>just</em> the number in the URL from LiveChat and paste in the <strong>License ID</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-settings" tabindex="-1">Step 4. Form Settings <a class="header-anchor" href="#step-4-form-settings" aria-label="Permalink to &quot;Step 4. Form Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the destination options offered by this integration and map required fields with the variable picker. For a support enquiry, map the visitor’s email and message where those fields are available.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Find the resulting enquiry in the selected account and check the sender details and submitted message.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const u=t(a,[["render",r]]);export{p as __pageData,u as default};
